({
  /**
   * Initializes the internal data structure for tracking request timestamps.
   */
  init(msg) {
    this.data = { clients: {} };
    this._checkInvariants();
    return { ok: true };
  },

  /**
   * Internal invariant check guaranteeing valid state in this.data.
   */
  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', 'this.data must be a valid object');
    this.invariant(this.data.clients && typeof this.data.clients === 'object', 'this.data.clients must be a valid dictionary');
    for (const [clientId, timestamps] of Object.entries(this.data.clients)) {
      this.invariant(typeof clientId === 'string', 'Stored client ID must be a string');
      this.invariant(Array.isArray(timestamps), 'Stored timestamps must be an array');
      for (let i = 0; i < timestamps.length; i++) {
        this.invariant(typeof timestamps[i] === 'number' && !Number.isNaN(timestamps[i]), 'Timestamp must be a valid number');
        if (i > 0) {
          this.invariant(timestamps[i] >= timestamps[i - 1], 'Timestamps must be recorded in non-decreasing order');
        }
      }
    }
  },

  /**
   * Ensures storage is initialized before use.
   */
  _ensureStorage() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = { clients: {} };
    }
    if (!this.data.clients || typeof this.data.clients !== 'object') {
      this.data.clients = {};
    }
  },

  /**
   * Checks whether a request is allowed within the specified sliding window.
   *
   * @param {Object} msg
   * @param {Object} msg.payload
   * @param {string} msg.payload.clientId - Identifier for the client.
   * @param {number} msg.payload.limit - Maximum number of requests allowed in window.
   * @param {number} msg.payload.windowMs - Sliding window duration in milliseconds.
   * @returns {{ allowed: boolean, remaining: number, resetAt: number }}
   */
  checkLimit(msg) {
    // Preconditions
    this.ensure(msg && typeof msg === 'object', 'Message must be an object');
    this.ensure(msg.payload && typeof msg.payload === 'object', 'Message payload is required');
    const { clientId, limit, windowMs } = msg.payload;

    this.ensure(typeof clientId === 'string' && clientId.trim().length > 0, 'clientId must be a non-empty string');
    this.ensure(typeof limit === 'number' && Number.isFinite(limit) && limit > 0, 'limit must be a positive number');
    this.ensure(typeof windowMs === 'number' && Number.isFinite(windowMs) && windowMs > 0, 'windowMs must be a positive number');

    this._ensureStorage();

    const now = Date.now();
    const windowStart = now - windowMs;

    const existingTimestamps = this.data.clients[clientId] || [];
    // Prune expired timestamps
    const activeTimestamps = existingTimestamps.filter(ts => ts > windowStart);

    let allowed = false;
    let remaining = 0;
    let resetAt = now + windowMs;

    if (activeTimestamps.length < limit) {
      activeTimestamps.push(now);
      allowed = true;
      remaining = Math.max(0, limit - activeTimestamps.length);
      this.data.clients[clientId] = activeTimestamps;
      this.changed('limitChecked', { clientId, allowed: true, remaining });
    } else {
      allowed = false;
      remaining = 0;
      this.data.clients[clientId] = activeTimestamps;
      this.changed('limitChecked', { clientId, allowed: false, remaining: 0 });
    }

    if (activeTimestamps.length > 0) {
      resetAt = activeTimestamps[0] + windowMs;
    }

    // Invariants check after state modification
    this._checkInvariants();

    const result = { allowed, remaining, resetAt };

    // Postconditions
    this.ensure(typeof result.allowed === 'boolean', 'allowed must be a boolean');
    this.ensure(typeof result.remaining === 'number' && result.remaining >= 0, 'remaining must be a non-negative number');
    this.ensure(typeof result.resetAt === 'number' && result.resetAt >= now, 'resetAt must be a valid future or current timestamp');

    return result;
  },

  /**
   * Resets rate limit records for a specific client or all clients.
   */
  reset(msg) {
    this._ensureStorage();
    const clientId = msg?.payload?.clientId;

    if (clientId) {
      this.ensure(typeof clientId === 'string', 'clientId must be a string when specified');
      delete this.data.clients[clientId];
      this.changed('reset', { clientId });
    } else {
      this.data.clients = {};
      this.changed('reset', { all: true });
    }

    this._checkInvariants();
    return { ok: true };
  }
})
